import subprocess, sys
def run(s, args=()):
    p = subprocess.run(['/workspace/executable', *args], input=s.encode(), capture_output=True)
    out = p.stdout.decode()
    i = out.find('<rect class="backdrop"')
    body = out[i:]
    body = body[body.find('\n')+1:]
    body = body.replace('</svg>\n','')
    return body
def show(s):
    print('=== ' + repr(s))
    for line in run(s).rstrip('\n').split('\n'):
        print('   ', line.strip())
if __name__ == '__main__':
    for a in sys.argv[1:]:
        show(a.replace('\\n', '\n'))
EOF
