import sys, itertools
sys.path.insert(0,'/tmp')
from h import elems
def gen(w, n_slash, n_bar, top_pad, tl=",'", tr="`.", bl="`.", br=".'"):
    lines = []
    ind1 = n_slash+1
    inner1 = w - 2*ind1 - 4
    if inner1 < 0: return None
    lines.append(' '*(ind1+2-top_pad) + '_'*(inner1 + 2*top_pad))
    lines.append(' '*ind1 + tl + ' '*inner1 + tr)
    for k in range(n_slash, 0, -1):
        lines.append(' '*k + '/' + ' '*(w-2*k-2) + '\\')
    for _ in range(n_bar):
        lines.append('|' + ' '*(w-2) + '|')
    for k in range(1, n_slash+1):
        lines.append(' '*k + '\\' + ' '*(w-2*k-2) + '/')
    lines.append(' '*ind1 + bl + '_'*inner1 + br)
    return '\n'.join(lines)
if __name__ == '__main__':
    w = int(sys.argv[1])
    for n_slash in [1,2,3]:
        for n_bar in [0,1,2,3,4,5]:
            for top_pad in [0,1]:
              for tl in [",'", ".'"]:
                a = gen(w, n_slash, n_bar, top_pad, tl=tl)
                if a is None: continue
                e = elems(a)
                ok = any(x.startswith('C(') for x in e) and len(e)==1
                if ok: print('MATCH', n_slash, n_bar, top_pad, e); print(a)
EOF
