    pub fn bounds(&self) -> (Point, Point) {
        (
            Point::new(self.start.x.min(self.end.x), self.start.y.min(self.end.y)),
            Point::new(self.start.x.max(self.end.x), self.start.y.max(self.end.y)),
        )
    }
    pub fn to_svg(&self, extra_classes: &[String]) -> String {
        let mut cls = "nofill".to_string();
        for c in extra_classes {
            cls.push(' ');
            cls.push_str(c);
        }
        format!(
            "<path d=\"M {},{} A {},{} 0,{},{} {},{}\" class=\"{}\"></path>",
            fmt(self.start.x),
            fmt(self.start.y),
            fmt(self.radius),
            fmt(self.radius),
            if self.large_arc { 1 } else { 0 },
            if self.sweep_flag { 1 } else { 0 },
            fmt(self.end.x),
            fmt(self.end.y),
            cls
        )
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Polygon {
    pub points: Vec<Point>,
    pub is_filled: bool,
}

impl Polygon {
    pub fn new(points: Vec<Point>, is_filled: bool) -> Self {
        Polygon { points, is_filled }
    }
    pub fn scale(&self, s: f32) -> Self {
        Polygon { points: self.points.iter().map(|p| p.scale(s)).collect(), is_filled: self.is_filled }
    }
    pub fn absolute_position(&self, cell: Cell) -> Self {
        Polygon { points: self.points.iter().map(|p| cell.absolute(*p)).collect(), is_filled: self.is_filled }
    }
    pub fn bounds(&self) -> (Point, Point) {
        let mut minx = f32::MAX;
        let mut miny = f32::MAX;
        let mut maxx = f32::MIN;
        let mut maxy = f32::MIN;
        for p in &self.points {
            minx = minx.min(p.x);
            miny = miny.min(p.y);
            maxx = maxx.max(p.x);
            maxy = maxy.max(p.y);
        }
        (Point::new(minx, miny), Point::new(maxx, maxy))
    }
    pub fn to_svg(&self, extra_classes: &[String]) -> String {
        let pts: Vec<String> = self.points.iter().map(|p| format!("{},{}", fmt(p.x), fmt(p.y))).collect();
        let mut cls = if self.is_filled { "filled".to_string() } else { "nofill".to_string() };
        for c in extra_classes {
            cls.push(' ');
            cls.push_str(c);
        }
        format!("<polygon points=\"{}\" class=\"{}\"></polygon>", pts.join(" "), cls)
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Rect {
    pub start: Point,
    pub end: Point,
    pub is_filled: bool,
    pub radius: Option<f32>,
    pub is_broken: bool,
}

impl Rect {
    pub fn new(start: Point, end: Point, is_filled: bool, is_broken: bool) -> Self {
        Rect { start, end, is_filled, radius: None, is_broken }
    }
    pub fn rounded_new(start: Point, end: Point, is_filled: bool, radius: f32, is_broken: bool) -> Self {
        Rect { start, end, is_filled, radius: Some(radius), is_broken }
    }
    pub fn scale(&self, s: f32) -> Self {
        Rect {
            start: self.start.scale(s),
            end: self.end.scale(s),
            is_filled: self.is_filled,
            radius: self.radius.map(|r| r * s),
            is_broken: self.is_broken,
        }
    }
    pub fn absolute_position(&self, cell: Cell) -> Self {
        Rect {
            start: cell.absolute(self.start),
            end: cell.absolute(self.end),
            is_filled: self.is_filled,
            radius: self.radius,
            is_broken: self.is_broken,
        }
    }
    pub fn bounds(&self) -> (Point, Point) {
        (
            Point::new(self.start.x.min(self.end.x), self.start.y.min(self.end.y)),
            Point::new(self.start.x.max(self.end.x), self.start.y.max(self.end.y)),
        )
    }
    pub fn width(&self) -> f32 {
        (self.end.x - self.start.x).abs()
    }
    pub fn height(&self) -> f32 {
        (self.end.y - self.start.y).abs()
    }
    pub fn to_svg(&self, extra_classes: &[String]) -> String {
        let mut cls = if self.is_broken { "broken".to_string() } else { "solid".to_string() };
        cls.push(' ');
        cls.push_str(if self.is_filled { "filled" } else { "nofill" });
        for c in extra_classes {
            cls.push(' ');
            cls.push_str(c);
        }
        let (tl, _) = self.bounds();
        format!(
            "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{}\" rx=\"{}\"></rect>",
            fmt(tl.x),
            fmt(tl.y),
            fmt(self.width()),
            fmt(self.height()),
            cls,
            fmt(self.radius.unwrap_or(0.0))
        )
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct CellText {
    pub cell: Cell,
    pub content: String,
}

impl CellText {
    pub fn new(cell: Cell, content: String) -> Self {
        CellText { cell, content }
    }
    pub fn absolute_position(&self, cell: Cell) -> Self {
        CellText { cell: Cell::new(self.cell.x + cell.x, self.cell.y + cell.y), content: self.content.clone() }
    }
    pub fn merge(&self, other: &CellText) -> Option<CellText> {
        if self.cell.y == other.cell.y && other.cell.x == self.cell.x + self.content.len() as i32 {
            Some(CellText { cell: self.cell, content: format!("{}{}", self.content, other.content) })
        } else {
            None
        }
    }
    /// bounds use the byte length of the content
    pub fn bounds(&self) -> (Point, Point) {
        let tl = self.cell.top_left();
        (
            tl,
            Point::new(
                (self.cell.x + self.content.len() as i32) as f32 * CELL_WIDTH,
                (self.cell.y + 1) as f32 * CELL_HEIGHT,
            ),
        )
    }
    pub fn start_point(&self) -> Point {
        let tl = self.cell.top_left();
        Point::new(tl.x + unit(1.0), tl.y + unit(6.0))
    }
    pub fn to_svg(&self, scale: f32, with_space: bool) -> String {
        let p = self.start_point().scale(scale);
        format!(
            "<text x=\"{}\" y=\"{}\"{}>{}</text>",
            fmt(p.x),
            fmt(p.y),
            if with_space { " " } else { "" },
            escape_text(&self.content)
        )
    }
}

pub fn escape_text(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(ch),
        }
    }
    out
}

#[derive(Debug, Clone, PartialEq)]
pub enum Fragment {
    Line(Line),
    MarkerLine(MarkerLine),
    Circle(Circle),
    Arc(Arc),
    Polygon(Polygon),
    Rect(Rect),
    CellText(CellText),
}

impl Fragment {
    pub fn absolute_position(&self, cell: Cell) -> Fragment {
        match self {
            Fragment::Line(l) => Fragment::Line(l.absolute_position(cell)),
            Fragment::MarkerLine(l) => Fragment::MarkerLine(l.absolute_position(cell)),
            Fragment::Circle(c) => Fragment::Circle(c.absolute_position(cell)),
            Fragment::Arc(a) => Fragment::Arc(a.absolute_position(cell)),
            Fragment::Polygon(p) => Fragment::Polygon(p.absolute_position(cell)),
            Fragment::Rect(r) => Fragment::Rect(r.absolute_position(cell)),
            Fragment::CellText(t) => Fragment::CellText(t.absolute_position(cell)),
        }
    }
    pub fn scale(&self, s: f32) -> Fragment {
        match self {
            Fragment::Line(l) => Fragment::Line(l.scale(s)),
            Fragment::MarkerLine(l) => Fragment::MarkerLine(l.scale(s)),
            Fragment::Circle(c) => Fragment::Circle(c.scale(s)),
            Fragment::Arc(a) => Fragment::Arc(a.scale(s)),
            Fragment::Polygon(p) => Fragment::Polygon(p.scale(s)),
            Fragment::Rect(r) => Fragment::Rect(r.scale(s)),
            Fragment::CellText(t) => Fragment::CellText(t.clone()),
        }
    }
    pub fn bounds(&self) -> (Point, Point) {
        match self {
            Fragment::Line(l) => l.bounds(),
            Fragment::MarkerLine(l) => l.line.bounds(),
            Fragment::Circle(c) => c.bounds(),
            Fragment::Arc(a) => a.bounds(),
            Fragment::Polygon(p) => p.bounds(),
            Fragment::Rect(r) => r.bounds(),
            Fragment::CellText(t) => t.bounds(),
        }
    }
    pub fn merge(&self, other: &Fragment) -> Option<Fragment> {
        match (self, other) {
            (Fragment::Line(a), Fragment::Line(b)) => a.merge(b).map(Fragment::Line),
            (Fragment::Line(l), Fragment::Circle(c)) => l.merge_circle(c),
            (Fragment::Circle(c), Fragment::Line(l)) => l.merge_circle(c),
            (Fragment::CellText(a), Fragment::CellText(b)) => a.merge(b).map(Fragment::CellText),
            _ => None,
        }
    }
    /// does this fragment make contact with the other
    pub fn is_contacting(&self, other: &Fragment) -> bool {
        match (self, other) {
            (Fragment::Line(a), Fragment::Line(b)) => a.is_touching(b),
            (Fragment::Line(l), Fragment::Arc(a)) | (Fragment::Arc(a), Fragment::Line(l)) => {
                l.start.is_near(&a.start) || l.start.is_near(&a.end) || l.end.is_near(&a.start) || l.end.is_near(&a.end)
            }
            (Fragment::Arc(a), Fragment::Arc(b)) => {
                a.start.is_near(&b.start) || a.start.is_near(&b.end) || a.end.is_near(&b.start) || a.end.is_near(&b.end)
            }
            (Fragment::CellText(a), Fragment::CellText(b)) => {
                let (amin, amax) = a.bounds();
                let (bmin, bmax) = b.bounds();
                amin.x < bmax.x && bmin.x < amax.x && amin.y < bmax.y && bmin.y < amax.y
            }
            _ => false,
        }
    }
    pub fn is_line(&self) -> bool {
        matches!(self, Fragment::Line(_))
    }
    pub fn is_text(&self) -> bool {
        matches!(self, Fragment::CellText(_))
    }
    pub fn as_line(&self) -> Option<&Line> {
        if let Fragment::Line(l) = self { Some(l) } else { None }
    }
    pub fn as_arc(&self) -> Option<&Arc> {
        if let Fragment::Arc(a) = self { Some(a) } else { None }
    }
    /// does this fragment (rect/circle/polygon) fully contain the other
    pub fn can_fit(&self, other: &Fragment) -> bool {
        match self {
            Fragment::Rect(_) | Fragment::Circle(_) | Fragment::Polygon(_) => {
                let (smin, smax) = self.bounds();
                let (omin, omax) = other.bounds();
                omin.x >= smin.x - EPS && omin.y >= smin.y - EPS && omax.x <= smax.x + EPS && omax.y <= smax.y + EPS
            }
            _ => false,
        }
    }
    pub fn to_svg(&self, scale: f32, extra_classes: &[String], text_space: bool) -> String {
        match self {
            Fragment::Line(l) => l.scale(scale).to_svg(extra_classes),
            Fragment::MarkerLine(l) => l.scale(scale).to_svg(extra_classes),
            Fragment::Circle(c) => c.scale(scale).to_svg(extra_classes),
            Fragment::Arc(a) => a.scale(scale).to_svg(extra_classes),
            Fragment::Polygon(p) => p.scale(scale).to_svg(extra_classes),
            Fragment::Rect(r) => r.scale(scale).to_svg(extra_classes),
            Fragment::CellText(t) => t.to_svg(scale, text_space),
        }
    }
}

/// ordering used when sorting fragments within a cell
impl PartialOrd for Fragment {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        let (a, _) = self.bounds();
        let (b, _) = other.bounds();
        Some(a.cmp(&b))
    }
}

pub fn line(a: Point, b: Point) -> Fragment {
    Fragment::Line(Line::new(a, b, false))
}
pub fn broken_line(a: Point, b: Point) -> Fragment {
    Fragment::Line(Line::new(a, b, true))
}
pub fn arc(a: Point, b: Point, r: f32) -> Fragment {
    Fragment::Arc(Arc::new(a, b, r))
}
pub fn circle(c: Point, r: f32, filled: bool) -> Fragment {
    Fragment::Circle(Circle::new(c, r, filled))
}
pub fn polygon(points: Vec<Point>, filled: bool) -> Fragment {
    Fragment::Polygon(Polygon::new(points, filled))
}
pub fn rect(a: Point, b: Point, filled: bool) -> Fragment {
    Fragment::Rect(Rect::new(a, b, filled, false))
}
