//! Fragments: the drawing primitives.
use crate::geom::{fmt, unit, Cell, Point, CELL_HEIGHT, CELL_WIDTH};
use std::cmp::Ordering;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Marker {
    Arrow,
    Diamond,
    Circle,
    OpenCircle,
    BigOpenCircle,
}

impl Marker {
    pub fn start_class(&self) -> &'static str {
        match self {
            Marker::Arrow => "start_marked_arrow",
            Marker::Diamond => "start_marked_diamond",
            Marker::Circle => "start_marked_circle",
            Marker::OpenCircle => "start_marked_open_circle",
            Marker::BigOpenCircle => "start_marked_big_open_circle",
        }
    }
    pub fn end_class(&self) -> &'static str {
        match self {
            Marker::Arrow => "end_marked_arrow",
            Marker::Diamond => "end_marked_diamond",
            Marker::Circle => "end_marked_circle",
            Marker::OpenCircle => "end_marked_open_circle",
            Marker::BigOpenCircle => "end_marked_big_open_circle",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Direction {
    TopLeft,
    Top,
    TopRight,
    Left,
    Right,
    BottomLeft,
    Bottom,
    BottomRight,
}

impl Direction {
    pub fn threshold_length(&self) -> f32 {
        match self {
            Direction::TopLeft
            | Direction::TopRight
            | Direction::BottomLeft
            | Direction::BottomRight => (CELL_WIDTH * CELL_WIDTH + CELL_HEIGHT * CELL_HEIGHT).sqrt(),
            Direction::Left | Direction::Right => CELL_WIDTH,
            Direction::Top | Direction::Bottom => CELL_HEIGHT,
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Line {
    pub start: Point,
    pub end: Point,
    pub is_broken: bool,
}

const EPS: f32 = 0.001;

fn near(a: f32, b: f32) -> bool {
    (a - b).abs() < EPS
}

impl Line {
    /// create a line, the end points are reordered such that start < end
    pub fn new(start: Point, end: Point, is_broken: bool) -> Self {
        let mut line = Line { start, end, is_broken };
        line.sort_reorder_end_points();
        line
    }
    pub fn new_noswap(start: Point, end: Point, is_broken: bool) -> Self {
        Line { start, end, is_broken }
    }
    pub fn sort_reorder_end_points(&mut self) {
        if self.start > self.end {
            std::mem::swap(&mut self.start, &mut self.end);
        }
    }
    pub fn absolute_position(&self, cell: Cell) -> Self {
        Line {
            start: cell.absolute(self.start),
            end: cell.absolute(self.end),
            is_broken: self.is_broken,
        }
    }
    pub fn scale(&self, s: f32) -> Self {
        Line {
            start: self.start.scale(s),
            end: self.end.scale(s),
            is_broken: self.is_broken,
        }
    }
    pub fn length(&self) -> f32 {
        self.start.distance(&self.end)
    }
    pub fn heading(&self) -> Direction {
        let dx = self.end.x - self.start.x;
        let dy = self.end.y - self.start.y;
        if near(dy, 0.0) {
            if dx >= 0.0 { Direction::Right } else { Direction::Left }
        } else if near(dx, 0.0) {
            if dy >= 0.0 { Direction::Bottom } else { Direction::Top }
        } else if dx > 0.0 {
            if dy > 0.0 { Direction::BottomRight } else { Direction::TopRight }
        } else if dy > 0.0 {
            Direction::BottomLeft
        } else {
            Direction::TopLeft
        }
    }
    pub fn is_horizontal(&self) -> bool {
        near(self.start.y, self.end.y)
    }
    pub fn is_vertical(&self) -> bool {
        near(self.start.x, self.end.x)
    }
    /// cross product based collinearity test with the other line
    pub fn is_collinear(&self, other: &Line) -> bool {
        collinear(self.start, self.end, other.start) && collinear(self.start, self.end, other.end)
    }
    /// check if point p lies on this segment (inclusive)
    pub fn contains_point(&self, p: Point) -> bool {
        if !collinear(self.start, self.end, p) {
            return false;
        }
        let minx = self.start.x.min(self.end.x) - EPS;
        let maxx = self.start.x.max(self.end.x) + EPS;
        let miny = self.start.y.min(self.end.y) - EPS;
        let maxy = self.start.y.max(self.end.y) + EPS;
        p.x >= minx && p.x <= maxx && p.y >= miny && p.y <= maxy
    }
    /// touching: an endpoint of one lies on the other
    pub fn is_touching(&self, other: &Line) -> bool {
        self.contains_point(other.start)
            || self.contains_point(other.end)
            || other.contains_point(self.start)
            || other.contains_point(self.end)
    }
    /// does this line fully cover the segment a-b
    pub fn overlaps(&self, a: Point, b: Point) -> bool {
        self.contains_point(a) && self.contains_point(b)
    }
    pub fn can_merge(&self, other: &Line) -> bool {
        self.is_collinear(other) && self.is_touching(other)
    }
    /// merge collinear touching lines
    pub fn merge(&self, other: &Line) -> Option<Line> {
        if self.can_merge(other) {
            let mut pts = [self.start, self.end, other.start, other.end];
            pts.sort();
            Some(Line::new(pts[0], pts[3], self.is_broken || other.is_broken))
        } else {
            None
        }
    }
    pub fn bounds(&self) -> (Point, Point) {
        (
            Point::new(self.start.x.min(self.end.x), self.start.y.min(self.end.y)),
            Point::new(self.start.x.max(self.end.x), self.start.y.max(self.end.y)),
        )
    }
    pub fn merge_circle(&self, circle: &Circle) -> Option<Fragment> {
        let distance_end_center = self.end.distance(&circle.center);
        let distance_start_center = self.start.distance(&circle.center);
        let threshold_length = self.heading().threshold_length();
        let is_close_start_point = distance_start_center < threshold_length;
        let is_close_end_point = distance_end_center < threshold_length;
        let can_merge = circle.radius <= unit(3.0) && (is_close_start_point || is_close_end_point);
        if can_merge {
            let marker = if circle.is_filled {
                Marker::Circle
            } else if circle.radius >= unit(2.0) {
                Marker::BigOpenCircle
            } else {
                Marker::OpenCircle
            };
            let new_line = if is_close_end_point {
                Line::new_noswap(self.start, circle.center, self.is_broken)
            } else {
                Line::new_noswap(self.end, circle.center, self.is_broken)
            };
            Some(Fragment::MarkerLine(MarkerLine {
                line: new_line,
                start_marker: None,
                end_marker: Some(marker),
            }))
        } else {
            None
        }
    }
    pub fn classes(&self) -> String {
        if self.is_broken { "broken".to_string() } else { "solid".to_string() }
    }
    pub fn to_svg(&self, extra_classes: &[String]) -> String {
        let mut cls = self.classes();
        for c in extra_classes {
            cls.push(' ');
            cls.push_str(c);
        }
        format!(
            "<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>",
            fmt(self.start.x),
            fmt(self.start.y),
            fmt(self.end.x),
            fmt(self.end.y),
            cls
        )
    }
}

fn collinear(a: Point, b: Point, c: Point) -> bool {
    let cross = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    cross.abs() < 0.01
}

#[derive(Debug, Clone, PartialEq)]
pub struct MarkerLine {
    pub line: Line,
    pub start_marker: Option<Marker>,
    pub end_marker: Option<Marker>,
}

impl MarkerLine {
    pub fn scale(&self, s: f32) -> Self {
        MarkerLine {
            line: self.line.scale(s),
            start_marker: self.start_marker,
            end_marker: self.end_marker,
