                //  |
                // /
                (bottom_left.is('/'), vec![l(C, M), l(M, U)]),
                (bottom_left.is('X') && !bottom_left.is('/'), vec![l(M, U)]),
                (bottom_right.is('X') && !bottom_right.is('\\'), vec![l(M, Y)]),
                // _
                //  |
                (top_left.is('_'), vec![l(A, C)]),
                //  _
                // |
                (top_right.is('_'), vec![l(C, E)]),
                // _|
                (left.is('_'), vec![l(U, W)]),
                // |_
                (right.is('_'), vec![l(W, Y)]),
                // -|
                (left.line_strongly_overlap(N, O), vec![l(K, M)]),
                // |-
                (right.line_strongly_overlap(K, L), vec![l(M, O)]),
