            (top.line_overlap(R, W), vec![l(C, M), l(M, Y)]),
            // -\
            (left.line_strongly_overlap(N, O), vec![l(K, M)]),
            // \-
            (right.line_strongly_overlap(K, L), vec![l(M, O)]),
        ],
        '+' => vec![
            (left.line_weakly_overlap(N, O), vec![l(K, M)]),
            (right.line_weakly_overlap(K, L), vec![l(M, O)]),
            (top.line_weakly_overlap(R, W), vec![l(C, M)]),
            (bottom.line_weakly_overlap(C, H), vec![l(M, W)]),
            (top_left.line_weakly_overlap(S, Y), vec![l(A, M)]),
            (top_right.line_weakly_overlap(Q, U), vec![l(E, M)]),
            (bottom_left.line_weakly_overlap(E, I), vec![l(M, U)]),
            (bottom_right.line_weakly_overlap(A, G), vec![l(M, Y)]),
        ],
        'X' => vec![
            (top_left.line_weakly_overlap(S, Y), vec![l(A, M)]),
            (top_right.line_weakly_overlap(Q, U), vec![l(E, M)]),
            (bottom_left.line_weakly_overlap(E, I), vec![l(M, U)]),
            (bottom_right.line_weakly_overlap(A, G), vec![l(M, Y)]),
