            ),
            //  .-
            // |
            (
                right.line_weakly_overlap(K, L) && bottom_left.line_weakly_overlap(C, H),
                vec![l(M, O), arc(M, Point::new(-unit2, unit(8.0)), unit4)],
            ),
            //  .-
            // /
            (
                right.line_weakly_overlap(K, L) && bottom_left.line_weakly_overlap(E, I),
