            ),
            // -.
            //   \
            (
                left.line_weakly_overlap(N, O) && bottom_right.line_weakly_overlap(A, G),
                vec![Fragment::Arc(Arc::new_flipped(K, S, unit4)), l(S, Y)],
            ),
            //  .
            // / \
            (
                bottom_left.line_weakly_overlap(E, I) && bottom_right.line_weakly_overlap(A, G),
                vec![l(M, U), l(M, Y)],
            ),
        ],
        ',' => vec![
            // ,-
            // |
            (
                right.line_weakly_overlap(K, L) && bottom.line_weakly_overlap(C, H),
                vec![arc(O, R, unit2), l(R, W)],
            ),
            //  ,-
            // /
            (
                right.line_weakly_overlap(K, L) && bottom_left.line_weakly_overlap(E, I),
                vec![arc(O, Q, unit4), l(Q, U)],
            ),
        ],
        '\'' => vec![
            // |
            // '-
            (
                right.line_weakly_overlap(K, L) && top.line_weakly_overlap(R, W),
                vec![arc(H, O, unit2), l(C, H)],
            ),
            //  |
            // -'
            (
                left.line_weakly_overlap(N, O) && top.line_weakly_overlap(R, W),
                vec![Fragment::Arc(Arc::new_flipped(H, K, unit2)), l(C, H)],
