            // |
            // '
            (
                top.line_strongly_overlap(R, W)
                    && !right.line_weakly_overlap(K, L)
                    && !left.line_weakly_overlap(N, O),
                vec![l(C, H)],
            ),
            //  \
            //   '-
            (
                right.line_weakly_overlap(K, L) && top_left.line_weakly_overlap(S, Y),
                vec![l(A, G), arc(G, O, unit4)],
            ),
            //    /
            //  -'
            (
                left.line_weakly_overlap(N, O) && top_right.line_weakly_overlap(Q, U),
                vec![l(E, I), Fragment::Arc(Arc::new_flipped(I, K, unit4))],
            ),
        ],
        '`' => vec![
            // |
            // `-
            (
                right.line_weakly_overlap(K, L) && top.line_weakly_overlap(R, W),
                vec![arc(H, O, unit2), l(C, H)],
            ),
            //  \
            //   `-
            (
                right.line_weakly_overlap(K, L) && top_left.line_weakly_overlap(S, Y),
                vec![l(A, G), arc(G, O, unit4)],
            ),
        ],
        '<' => vec![
            // <-
            (right.line_strongly_overlap(K, L), vec![arrow_left()]),
            // -<
            (left.line_strongly_overlap(N, O), vec![l(J, K), l(K, T)]),
        ],
        '>' => vec![
            // ->
            (left.line_strongly_overlap(N, O), vec![arrow_right()]),
            // >-
            (right.line_strongly_overlap(K, L), vec![l(F, O), l(O, P)]),
        ],
        '^' => vec![
            // ^
            // |
            (bottom.line_weakly_overlap(C, H), vec![arrow_up(), l(R, W)]),
            // |
            // ^
            (top.line_strongly_overlap(R, W), vec![l(C, U), l(C, Y)]),
        ],
        'v' | 'V' => vec![
            // |
            // v
            (top.line_weakly_overlap(R, W), vec![arrow_down(), l(C, H)]),
            // v
            // |
            (bottom.line_strongly_overlap(C, H), vec![l(A, W), l(E, W)]),
        ],
        '(' => vec![
            (
                !top.line_weakly_overlap(R, W) && !bottom.line_weakly_overlap(C, H),
                vec![arc(E, Y, unit8)],
            ),
            (
                !top.line_weakly_overlap(R, W) && bottom.line_weakly_overlap(C, H),
                vec![arc(C, W, unit6)],
            ),
        ],
        ')' => vec![(
            !top.line_weakly_overlap(R, W) && !bottom.line_weakly_overlap(C, H),
            vec![Fragment::Arc(Arc::new_flipped(A, U, unit8))],
        )],
        _ => return None,
    };
    Some(rules)
}
