actions.command:
cat > /workspace/src/property.rs <<'EOF'
//! Character properties: signatures and behaviors.
use crate::fragment::*;
use crate::geom::grid::*;
use crate::geom::{unit, Point};

#[derive(Debug, Clone, Copy, PartialEq, PartialOrd)]
pub enum Signal {
    Weak,
    Medium,
    Strong,
}

#[derive(Debug, Clone)]
pub struct Property {
    pub ch: char,
    pub signature: Vec<(Signal, Vec<Fragment>)>,
}

impl Property {
    pub fn empty() -> Property {
        Property { ch: ' ', signature: vec![] }
    }
    pub fn from_char(ch: char) -> Option<Property> {
        if let Some(sig) = signature(ch) {
            Some(Property { ch, signature: sig })
        } else if let Some(frags) = crate::unicode_map::fragments(ch) {
            Some(Property { ch, signature: vec![(Signal::Strong, frags)] })
        } else {
            None
        }
    }
    pub fn is(&self, ch: char) -> bool {
        self.ch == ch
    }
    pub fn any(&self, s: &str) -> bool {
        s.contains(self.ch)
    }
    pub fn is_empty(&self) -> bool {
        self.ch == ' '
    }
    fn line_overlap_with_signal(&self, a: Point, b: Point, required: Signal) -> bool {
        self.signature
            .iter()
            .filter(|(sig, _)| *sig >= required)
            .flat_map(|(_, frags)| frags.iter())
            .any(|f| match f {
                Fragment::Line(l) => l.overlaps(a, b),
                _ => false,
            })
    }
    /// at least medium
    pub fn line_overlap(&self, a: Point, b: Point) -> bool {
        self.line_overlap_with_signal(a, b, Signal::Medium)
    }
    pub fn line_strongly_overlap(&self, a: Point, b: Point) -> bool {
        self.line_overlap_with_signal(a, b, Signal::Strong)
    }
    /// any signal
    pub fn line_weakly_overlap(&self, a: Point, b: Point) -> bool {
        self.line_overlap_with_signal(a, b, Signal::Weak)
    }
    pub fn is_strong(&self) -> bool {
        self.signature.iter().any(|(s, _)| *s == Signal::Strong)
    }
}

pub struct Neighbors<'a> {
    pub top_left: &'a Property,
    pub top: &'a Property,
    pub top_right: &'a Property,
    pub left: &'a Property,
    pub right: &'a Property,
    pub bottom_left: &'a Property,
    pub bottom: &'a Property,
    pub bottom_right: &'a Property,
}

fn l(a: Point, b: Point) -> Fragment {
    line(a, b)
}

/// signature of the ascii characters
pub fn signature(ch: char) -> Option<Vec<(Signal, Vec<Fragment>)>> {
    use Signal::*;
    let unit3 = unit(3.0);
    let unit5 = unit(5.0);
    let p03 = Point::new(0.0, unit3);
    let p43 = Point::new(unit(4.0), unit3);
    let p05 = Point::new(0.0, unit5);
    let p45 = Point::new(unit(4.0), unit5);
    let sig = match ch {
        '-' => vec![(Strong, vec![l(K, O)])],
        '=' => vec![(Strong, vec![l(p03, p43), l(p05, p45)])],
        '~' => vec![(Strong, vec![broken_line(K, O)])],
        '_' => vec![(Strong, vec![l(U, Y)])],
        '|' => vec![(Strong, vec![l(C, W)])],
        ':' | '!' => vec![(Strong, vec![broken_line(C, W)])],
        '/' => vec![(Strong, vec![l(E, U)])],
        '\\' => vec![(Strong, vec![l(A, Y)])],
        '+' => vec![(Medium, vec![l(K, O), l(C, W)])],
        'X' => vec![(Medium, vec![l(A, Y), l(E, U)])],
        'x' => vec![],
        '.' => vec![(Weak, vec![l(K, O), l(M, W)])],
        ',' => vec![(Weak, vec![l(K, O)])],
        '\'' => vec![(Weak, vec![l(K, O), l(C, M)])],
        '`' => vec![(Medium, vec![l(K, O), l(C, M)])],
        'o' | 'O' => vec![(Medium, vec![l(K, O)])],
        '*' => vec![(Medium, vec![l(K, O), l(C, W)])],
        '#' => vec![(Medium, vec![l(K, O), l(C, W)])],
        '<' | '>' | '^' | 'v' | 'V' => vec![],
        '(' => vec![(Medium, vec![arc(E, Y, unit(8.0))])],
        ')' => vec![(Medium, vec![Fragment::Arc(Arc::new_flipped(A, U, unit(8.0)))])],
        _ => return None,
    };
    Some(sig)
}

/// compute the fragments for a character given its neighbors
pub fn fragments(ch: char, n: &Neighbors) -> Option<Vec<Fragment>> {
    let rules = behavior(ch, n)?;
    Some(
        rules
            .into_iter()
            .filter_map(|(cond, frags)| if cond { Some(frags) } else { None })
            .flatten()
            .collect(),
    )
}

fn arrow_up() -> Fragment {
    polygon(vec![P, C, T], true)
}
fn arrow_down() -> Fragment {
    polygon(vec![F, J, W], true)
}
fn arrow_left() -> Fragment {
    polygon(vec![J, K, T], true)
}
fn arrow_right() -> Fragment {
    polygon(vec![F, O, P], true)
}

fn behavior(ch: char, n: &Neighbors) -> Option<Vec<(bool, Vec<Fragment>)>> {
    let Neighbors { top_left, top, top_right, left, right, bottom_left, bottom, bottom_right } = *n;
    let unit1_5 = unit(1.5);
    let unit2 = unit(2.0);
    let unit3 = unit(3.0);
    let unit4 = unit(4.0);
    let unit5 = unit(5.0);
    let unit6 = unit(6.0);
    let unit8 = unit(8.0);
    let p03 = Point::new(0.0, unit3);
    let p43 = Point::new(unit4, unit3);
    let p05 = Point::new(0.0, unit5);
    let p45 = Point::new(unit4, unit5);

    let rules: Vec<(bool, Vec<Fragment>)> = match ch {
        '-' => vec![(true, vec![l(K, O)])],
        '=' => vec![(true, vec![l(p03, p43), l(p05, p45)])],
        '~' => vec![(true, vec![broken_line(K, O)])],
        '_' => vec![(true, vec![l(U, Y)])],
        '|' => {
            let is_text = top_left.is('\\') || top_right.is('/');
            vec![
                (
                    !is_text && !bottom_left.is('/') && !bottom_right.is('\\'),
                    vec![l(C, W)],
                ),
                // |
                //  \
                (bottom_right.is('\\'), vec![l(C, M), l(M, Y)]),
                //  |
                // /
                (bottom_left.is('/'), vec![l(C, M), l(M, U)]),
                (bottom_left.is('X') && !bottom_left.is('/'), vec![l(M, U)]),
                (bottom_right.is('X') && !bottom_right.is('\\'), vec![l(M, Y)]),
                // _
                //  |
                (top_left.is('_'), vec![l(A, C)]),
                //  _
                // |
                (top_right.is('_'), vec![l(C, E)]),
                // _|
                (left.is('_'), vec![l(U, W)]),
                // |_
                (right.is('_'), vec![l(W, Y)]),
                // -|
                (left.line_strongly_overlap(N, O), vec![l(K, M)]),
                // |-
                (right.line_strongly_overlap(K, L), vec![l(M, O)]),
            ]
        }
        ':' | '!' => vec![(
            top.line_strongly_overlap(R, W) || bottom.line_strongly_overlap(C, H),
            vec![broken_line(C, W)],
        )],
        '/' => vec![
            (!bottom.line_overlap(C, H) && !top.line_overlap(R, W), vec![l(E, U)]),
            // /
            // |
            (bottom.line_overlap(C, H), vec![l(E, M), l(M, W)]),
            // |
            // /
            (top.line_overlap(R, W), vec![l(C, M), l(M, U)]),
            // -/
            (left.line_strongly_overlap(N, O), vec![l(K, M)]),
            // /-
            (right.line_strongly_overlap(K, L), vec![l(M, O)]),
        ],
        '\\' => vec![
            (!bottom.line_overlap(C, H) && !top.line_overlap(R, W), vec![l(A, Y)]),
            // \
            // |
            (bottom.line_overlap(C, H), vec![l(A, M), l(M, W)]),
            // |
            // \
            (top.line_overlap(R, W), vec![l(C, M), l(M, Y)]),
            // -\
            (left.line_strongly_overlap(N, O), vec![l(K, M)]),
            // \-
            (right.line_strongly_overlap(K, L), vec![l(M, O)]),
        ],
        '+' => vec![
            (left.line_weakly_overlap(N, O), vec![l(K, M)]),
            (right.line_weakly_overlap(K, L), vec![l(M, O)]),
            (top.line_weakly_overlap(R, W), vec![l(C, M)]),
            (bottom.line_weakly_overlap(C, H), vec![l(M, W)]),
            (top_left.line_weakly_overlap(S, Y), vec![l(A, M)]),
            (top_right.line_weakly_overlap(Q, U), vec![l(E, M)]),
            (bottom_left.line_weakly_overlap(E, I), vec![l(M, U)]),
            (bottom_right.line_weakly_overlap(A, G), vec![l(M, Y)]),
        ],
        'X' => vec![
            (top_left.line_weakly_overlap(S, Y), vec![l(A, M)]),
            (top_right.line_weakly_overlap(Q, U), vec![l(E, M)]),
            (bottom_left.line_weakly_overlap(E, I), vec![l(M, U)]),
            (bottom_right.line_weakly_overlap(A, G), vec![l(M, Y)]),
            (top.line_strongly_overlap(R, W), vec![l(C, M)]),
            (bottom.line_strongly_overlap(C, H), vec![l(M, W)]),
        ],
        'x' => vec![
            (top_left.line_strongly_overlap(S, Y), vec![l(A, M)]),
            (top_right.line_strongly_overlap(Q, U), vec![l(E, M)]),
            (bottom_left.line_strongly_overlap(E, I), vec![l(M, U)]),
            (bottom_right.line_strongly_overlap(A, G), vec![l(M, Y)]),
        ],
        'o' | 'O' | '*' => {
            let (radius, filled) = match ch {
                'o' => (unit1_5, false),
                'O' => (unit2, false),
                _ => (unit1_5, true),
            };
            let is_circle = left.line_strongly_overlap(N, O)
                || right.line_strongly_overlap(K, L)
                || top.line_strongly_overlap(R, W)
                || bottom.line_strongly_overlap(C, H)
                || top_left.line_strongly_overlap(S, Y)
                || top_right.line_strongly_overlap(Q, U)
                || bottom_left.line_strongly_overlap(E, I)
                || bottom_right.line_strongly_overlap(A, G);
            let is_star = ch == '*';
            vec![
                (top_left.line_overlap(S, Y), vec![l(A, G)]),
                (top.line_overlap(R, W), vec![l(C, H)]),
                (top_right.line_overlap(Q, U), vec![l(E, I)]),
                (is_circle, vec![circle(M, radius, filled)]),
                (is_star && left.line_overlap(N, O), vec![l(K, M)]),
                (is_star && right.line_overlap(K, L), vec![l(M, O)]),
                (bottom_left.line_overlap(E, I), vec![l(Q, U)]),
                (bottom.line_overlap(C, H), vec![l(R, W)]),
                (bottom_right.line_overlap(A, G), vec![l(S, Y)]),
            ]
        }
        '#' => {
            let is_square = left.line_strongly_overlap(N, O)
                || right.line_strongly_overlap(K, L)
                || top.line_strongly_overlap(R, W)
                || bottom.line_strongly_overlap(C, H)
                || top_left.line_strongly_overlap(S, Y)
                || top_right.line_strongly_overlap(Q, U)
                || bottom_left.line_strongly_overlap(E, I)
                || bottom_right.line_strongly_overlap(A, G);
            vec![
                (top.line_overlap(R, W), vec![l(C, H)]),
                (is_square, vec![rect(F, T, true)]),
                (left.line_overlap(N, O), vec![l(K, L)]),
                (right.line_overlap(K, L), vec![l(N, O)]),
                (bottom.line_weakly_overlap(C, H), vec![l(R, W)]),
            ]
        }
        '.' => vec![
            // .-
            // |
            (
                right.line_weakly_overlap(K, L) && bottom.line_weakly_overlap(C, H),
                vec![arc(O, R, unit2), l(R, W)],
            ),
            // -.
            //  |
            (
                left.line_weakly_overlap(N, O) && bottom.line_weakly_overlap(C, H),
                vec![Fragment::Arc(Arc::new_flipped(K, R, unit2)), l(R, W)],
            ),
            // .
            // |
            (
                bottom.line_weakly_overlap(C, H)
                    && !right.line_weakly_overlap(K, L)
                    && !left.line_weakly_overlap(N, O),
                vec![l(R, W)],
            ),
            // -.
            //   |
            (
                left.line_weakly_overlap(N, O) && bottom_right.line_weakly_overlap(C, H),
                vec![l(K, M), Fragment::Arc(Arc::new_flipped(M, Point::new(unit(6.0), unit(8.0)), unit4))],
            ),
            //  .-
            // |
            (
                right.line_weakly_overlap(K, L) && bottom_left.line_weakly_overlap(C, H),
                vec![l(M, O), arc(M, Point::new(-unit2, unit(8.0)), unit4)],
            ),
            //  .-
            // /
            (
                right.line_weakly_overlap(K, L) && bottom_left.line_weakly_overlap(E, I),
                vec![arc(O, Q, unit4), l(Q, U)],
            ),
            // -.
            //   \
            (
                left.line_weakly_overlap(N, O) && bottom_right.line_weakly_overlap(A, G),
                vec![Fragment::Arc(Arc::new_flipped(K, S, unit4)), l(S, Y)],
            ),
            //  .
            // / \
            (
                bottom_left.line_weakly_overlap(E, I) && bottom_right.line_weakly_overlap(A, G),
                vec![l(M, U), l(M, Y)],
            ),
        ],
        ',' => vec![
            // ,-
            // |
            (
                right.line_weakly_overlap(K, L) && bottom.line_weakly_overlap(C, H),
                vec![arc(O, R, unit2), l(R, W)],
            ),
            //  ,-
            // /
            (
                right.line_weakly_overlap(K, L) && bottom_left.line_weakly_overlap(E, I),
                vec![arc(O, Q, unit4), l(Q, U)],
            ),
        ],
        '\'' => vec![
            // |
            // '-
            (
                right.line_weakly_overlap(K, L) && top.line_weakly_overlap(R, W),
                vec![arc(H, O, unit2), l(C, H)],
            ),
            //  |
            // -'
            (
                left.line_weakly_overlap(N, O) && top.line_weakly_overlap(R, W),
                vec![Fragment::Arc(Arc::new_flipped(H, K, unit2)), l(C, H)],
            ),
            // |
            // '
            (
                top.line_strongly_overlap(R, W)
                    && !right.line_weakly_overlap(K, L)
                    && !left.line_weakly_overlap(N, O),
                vec![l(C, H)],
            ),
            //  \
            //   '-
            (
                right.line_weakly_overlap(K, L) && top_left.line_weakly_overlap(S, Y),
                vec![l(A, G), arc(G, O, unit4)],
            ),
            //    /
            //  -'
            (
                left.line_weakly_overlap(N, O) && top_right.line_weakly_overlap(Q, U),
                vec![l(E, I), Fragment::Arc(Arc::new_flipped(I, K, unit4))],
            ),
        ],
        '`' => vec![
            // |
            // `-
            (
                right.line_weakly_overlap(K, L) && top.line_weakly_overlap(R, W),
                vec![arc(H, O, unit2), l(C, H)],
            ),
            //  \
            //   `-
            (
                right.line_weakly_overlap(K, L) && top_left.line_weakly_overlap(S, Y),
