//! Cell buffer: parsing text into cells, grouping, merging and rendering.
use crate::circle_map;
use crate::fragment::*;
use crate::geom::{fmt, Cell, Point, CELL_HEIGHT, CELL_WIDTH};
use crate::property::{fragments, Neighbors, Property};
use crate::settings::Settings;
use std::collections::BTreeMap;
use unicode_width::UnicodeWidthChar;

#[derive(Debug, Clone, Default)]
pub struct Span(pub Vec<(Cell, char)>);

impl Span {
    pub fn new(cell: Cell, ch: char) -> Self {
        Span(vec![(cell, ch)])
    }
    pub fn is_adjacent(&self, cell: &Cell) -> bool {
        self.0.iter().any(|(c, _)| c.is_adjacent(cell))
    }
    pub fn can_merge(&self, other: &Span) -> bool {
        self.0.iter().any(|(c, _)| other.is_adjacent(c))
    }
    pub fn merge(&mut self, other: &Span) {
        self.0.extend(other.0.iter().cloned());
    }
    pub fn bounds(&self) -> Option<(Cell, Cell)> {
        if self.0.is_empty() {
            return None;
        }
        let minx = self.0.iter().map(|(c, _)| c.x).min().unwrap();
        let miny = self.0.iter().map(|(c, _)| c.y).min().unwrap();
        let maxx = self.0.iter().map(|(c, _)| c.x).max().unwrap();
        let maxy = self.0.iter().map(|(c, _)| c.y).max().unwrap();
        Some((Cell::new(minx, miny), Cell::new(maxx, maxy)))
    }
    /// cells in sorted order
    pub fn sorted_map(&self) -> BTreeMap<Cell, char> {
        self.0.iter().cloned().collect()
    }
    fn merge_recursive(spans: Vec<Span>) -> Vec<Span> {
        let original_len = spans.len();
        let merged = Self::second_pass_merge(spans);
        if merged.len() < original_len {
            Self::merge_recursive(merged)
        } else {
            merged
        }
    }
    fn second_pass_merge(spans: Vec<Span>) -> Vec<Span> {
        let mut new_groups: Vec<Span> = vec![];
        for span in spans.into_iter() {
            let is_merged = new_groups.iter_mut().rev().any(|g| {
                if g.can_merge(&span) {
                    g.merge(&span);
                    true
                } else {
                    false
                }
            });
            if !is_merged {
                new_groups.push(span);
            }
        }
        new_groups
    }

    /// convert the cells of this span into fragments (absolute positions, merged)
    pub fn into_fragments(&self) -> Vec<Fragment> {
        let cells = self.sorted_map();
        let empty = Property::empty();
        let props: BTreeMap<Cell, Option<Property>> =
            cells.iter().map(|(c, ch)| (*c, Property::from_char(*ch))).collect();
        let get = |cell: Cell| -> &Property {
            match props.get(&cell) {
                Some(Some(p)) => p,
                _ => &empty,
            }
        };
        let mut per_cell: Vec<(Cell, Vec<Fragment>)> = vec![];
        for (cell, ch) in cells.iter() {
            let frags = match props.get(cell) {
                Some(Some(_)) => {
                    let n = Neighbors {
                        top_left: get(cell.top_left()),
                        top: get(cell.top()),
                        top_right: get(cell.top_right()),
                        left: get(cell.left()),
                        right: get(cell.right()),
                        bottom_left: get(cell.bottom_left()),
                        bottom: get(cell.bottom()),
                        bottom_right: get(cell.bottom_right()),
                    };
                    let mut frags = fragments(*ch, &n).unwrap_or_default();
                    if frags.is_empty() {
                        vec![Fragment::CellText(CellText::new(Cell::new(0, 0), ch.to_string()))]
                    } else {
                        frags.sort_by(|a, b| {
                            let (amin, amax) = a.bounds();
                            let (bmin, bmax) = b.bounds();
                            amin.cmp(&bmin).then(amax.cmp(&bmax))
                        });
                        frags
                    }
                }
                _ => vec![Fragment::CellText(CellText::new(Cell::new(0, 0), ch.to_string()))],
            };
            per_cell.push((*cell, frags));
        }
        // first pass merge
        let mut merged: Vec<Fragment> = vec![];
        for (cell, frags) in per_cell.iter() {
            for frag in frags.iter() {
                let abs = frag.absolute_position(*cell);
                let had_merged = merged.iter_mut().rev().any(|m| {
                    if let Some(new) = m.merge(&abs) {
                        *m = new;
                        true
                    } else {
                        false
                    }
                });
                if !had_merged {
                    merged.push(abs);
                }
            }
        }
        merge_recursive(merged)
    }
}

fn merge_recursive(fragments: Vec<Fragment>) -> Vec<Fragment> {
    let original_len = fragments.len();
    let merged = second_pass_merge(fragments);
    if merged.len() < original_len {
        merge_recursive(merged)
    } else {
        merged
    }
}

fn second_pass_merge(fragments: Vec<Fragment>) -> Vec<Fragment> {
    let mut new_fragments: Vec<Fragment> = vec![];
    for fragment in fragments.into_iter() {
        let is_merged = new_fragments.iter_mut().rev().any(|nf| {
            if let Some(new) = nf.merge(&fragment) {
                *nf = new;
                true
            } else {
                false
            }
        });
        if !is_merged {
            new_fragments.push(fragment);
        }
    }
    new_fragments
}

/// a group of fragments that are touching each other
#[derive(Debug, Clone)]
pub struct Contacts(pub Vec<Fragment>);

impl Contacts {
    fn is_contacting_frag(&self, frag: &Fragment) -> bool {
        self.0.iter().any(|f| f.is_contacting(frag))
    }
    fn can_merge(&self, other: &Contacts) -> bool {
        self.0.iter().any(|f| other.is_contacting_frag(f))
    }
    fn merge_recursive(groups: Vec<Contacts>) -> Vec<Contacts> {
        let original_len = groups.len();
        let merged = Self::second_pass_merge(groups);
        if merged.len() < original_len {
            Self::merge_recursive(merged)
        } else {
            merged
        }
    }
    fn second_pass_merge(groups: Vec<Contacts>) -> Vec<Contacts> {
        let mut new_groups: Vec<Contacts> = vec![];
        for group in groups.into_iter() {
            let is_merged = new_groups.iter_mut().rev().any(|g| {
                if g.can_merge(&group) {
                    g.0.extend(group.0.iter().cloned());
                    true
                } else {
                    false
                }
            });
            if !is_merged {
                new_groups.push(group);
            }
        }
        new_groups
    }
}

pub fn get_contacts(fragments: Vec<Fragment>) -> Vec<Contacts> {
    let mut groups: Vec<Contacts> = vec![];
    for fragment in fragments.into_iter() {
        let belongs = groups.iter_mut().rev().any(|g| {
            if g.is_contacting_frag(&fragment) {
                g.0.push(fragment.clone());
                true
            } else {
                false
            }
        });
        if !belongs {
            groups.push(Contacts(vec![fragment]));
        }
    }
    Contacts::merge_recursive(groups)
}

/// try to endorse a group of fragments into a rect
pub fn endorse_rect(frags: &[Fragment]) -> Option<Fragment> {
    let lines: Vec<&Line> = frags.iter().filter_map(|f| f.as_line()).collect();
    let arcs: Vec<&Arc> = frags.iter().filter_map(|f| f.as_arc()).collect();
    if lines.len() + arcs.len() != frags.len() {
        return None;
    }
    if lines.len() != 4 {
        return None;
    }
    let horizontals: Vec<&Line> = lines.iter().cloned().filter(|l| l.is_horizontal()).collect();
    let verticals: Vec<&Line> = lines.iter().cloned().filter(|l| l.is_vertical()).collect();
    if horizontals.len() != 2 || verticals.len() != 2 {
        return None;
    }
    let (h1, h2) = (horizontals[0], horizontals[1]);
    let (v1, v2) = (verticals[0], verticals[1]);
    let near = |a: f32, b: f32| (a - b).abs() < 0.01;
    // horizontals must have the same x range, verticals the same y range
    if !(near(h1.start.x, h2.start.x) && near(h1.end.x, h2.end.x)) {
        return None;
    }
    if !(near(v1.start.y, v2.start.y) && near(v1.end.y, v2.end.y)) {
        return None;
    }
    let is_broken = lines.iter().any(|l| l.is_broken);
    if arcs.is_empty() {
        // sharp rect: verticals at the ends of the horizontals
        let (hx1, hx2) = (h1.start.x.min(h1.end.x), h1.start.x.max(h1.end.x));
        let (vx1, vx2) = (v1.start.x.min(v2.start.x), v1.start.x.max(v2.start.x));
        if !(near(hx1, vx1) && near(hx2, vx2)) {
            return None;
        }
        let (vy1, vy2) = (v1.start.y.min(v1.end.y), v1.start.y.max(v1.end.y));
        let (hy1, hy2) = (h1.start.y.min(h2.start.y), h1.start.y.max(h2.start.y));
        if !(near(vy1, hy1) && near(vy2, hy2)) {
            return None;
        }
        Some(Fragment::Rect(Rect::new(Point::new(hx1, hy1), Point::new(hx2, hy2), false, is_broken)))
    } else if arcs.len() == 4 {
        let r = arcs[0].radius;
        if !arcs.iter().all(|a| near(a.radius, r)) {
            return None;
        }
        // every arc must connect a horizontal end to a vertical end
        let line_ends: Vec<Point> = lines.iter().flat_map(|l| vec![l.start, l.end]).collect();
        for a in &arcs {
            let s_ok = line_ends.iter().any(|p| p.is_near(&a.start));
            let e_ok = line_ends.iter().any(|p| p.is_near(&a.end));
            if !(s_ok && e_ok) {
                return None;
            }
        }
        let mut minx = f32::MAX;
        let mut miny = f32::MAX;
        let mut maxx = f32::MIN;
        let mut maxy = f32::MIN;
        for f in frags {
            let (a, b) = f.bounds();
            minx = minx.min(a.x);
            miny = miny.min(a.y);
            maxx = maxx.max(b.x);
            maxy = maxy.max(b.y);
        }
        Some(Fragment::Rect(Rect::rounded_new(Point::new(minx, miny), Point::new(maxx, maxy), false, r, is_broken)))
    } else {
        None
    }
}

#[derive(Debug, Clone)]
pub struct CellBuffer {
    pub cells: BTreeMap<Cell, char>,
    pub legend: Vec<(String, String)>,
}

impl CellBuffer {
    pub fn from_str(input: &str) -> CellBuffer {
        let mut cells = BTreeMap::new();
        let mut legend = vec![];
        let mut in_legend = false;
        for (y, line) in input.split('\n').enumerate() {
            if in_legend {
                if let Some(entry) = parse_legend_line(line) {
                    legend.push(entry);
                }
                continue;
            }
            if line.trim() == "# Legend:" {
                in_legend = true;
                continue;
            }
            let mut x: i32 = 0;
            for ch in line.chars() {
                let width = ch.width().unwrap_or(1).max(1) as i32;
                if !ch.is_whitespace() {
                    cells.insert(Cell::new(x, y as i32), ch);
                }
                x += width;
            }
        }
        CellBuffer { cells, legend }
    }

    pub fn group_adjacents(&self) -> Vec<Span> {
        let mut adjacents: Vec<Span> = vec![];
        for (cell, ch) in self.cells.iter() {
            let belongs = adjacents.iter_mut().rev().any(|span| {
                if span.is_adjacent(cell) {
                    span.0.push((*cell, *ch));
                    true
                } else {
                    false
                }
            });
            if !belongs {
                adjacents.push(Span::new(*cell, *ch));
            }
        }
        Span::merge_recursive(adjacents)
    }

    /// bounding cell (max) of all cells
    fn bounding_cell(&self) -> Cell {
        let mut maxx = 0;
        let mut maxy = 0;
        for (c, ch) in self.cells.iter() {
            let w = ch.width().unwrap_or(1).max(1) as i32;
            maxx = maxx.max(c.x + w - 1);
            maxy = maxy.max(c.y);
        }
        Cell::new(maxx, maxy)
    }

    pub fn to_svg(&self, settings: &Settings) -> String {
        let (endorsed, singles, groups) = self.process();
        let br = self.bounding_cell();
        let w = (br.x + 2) as f32 * CELL_WIDTH * settings.scale;
        let h = (br.y + 2) as f32 * CELL_HEIGHT * settings.scale;
        let mut out = String::new();
        out.push_str(&format!(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n",
            fmt(w),
            fmt(h)
        ));
        out.push_str(&style(settings, &self.legend));
        out.push_str(DEFS);
        out.push_str(&format!(
            "  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n",
            fmt(w),
            fmt(h)
        ));
        // fragment tree for endorsed + singles
        let mut all: Vec<Fragment> = endorsed;
        all.extend(singles);
        let trees = FragmentTree::enclose_fragments(all);
        for tree in trees {
            tree.render(settings, &mut out, "  ");
        }
        for group in groups {
            out.push_str("  <g>\n");
            for f in group {
                out.push_str("    ");
                out.push_str(&f.to_svg(settings.scale, &[], false));
                out.push('\n');
            }
            out.push_str("  </g>\n");
        }
        out.push_str("</svg>");
        out
    }

    /// returns (endorsed fragments, single member fragments, groups)
    fn process(&self) -> (Vec<Fragment>, Vec<Fragment>, Vec<Vec<Fragment>>) {
        let mut endorsed: Vec<Fragment> = vec![];
        let mut singles: Vec<Fragment> = vec![];
        let mut groups: Vec<Vec<Fragment>> = vec![];
        for span in self.group_adjacents() {
            let (accepted, contacts) = endorse_span(span);
            endorsed.extend(accepted);
            for c in contacts {
                if c.0.len() == 1 {
                    singles.extend(c.0);
                } else {
                    groups.push(c.0);
                }
            }
        }
        (endorsed, singles, groups)
    }
}

/// endorse a span: circles, arcs, rects
fn endorse_span(span: Span) -> (Vec<Fragment>, Vec<Contacts>) {
    let mut accepted: Vec<Fragment> = vec![];
    let mut remaining = span;
    loop {
        if let Some((frag, rest)) = circle_map::endorse(&remaining) {
            accepted.push(frag);
            remaining = rest;
            if remaining.0.is_empty() {
                break;
            }
        } else {
            break;
        }
    }
    if remaining.0.is_empty() {
        return (accepted, vec![]);
    }
    let fragments = remaining.into_fragments();
    let contacts = get_contacts(fragments);
    let mut un_endorsed: Vec<Contacts> = vec![];
    for c in contacts {
        if let Some(rect) = endorse_rect(&c.0) {
            accepted.push(rect);
        } else {
            un_endorsed.push(c);
        }
    }
    (accepted, un_endorsed)
}

fn parse_legend_line(line: &str) -> Option<(String, String)> {
    let line = line.trim();
    if line.is_empty() {
        return None;
    }
    let eq = line.find('=')?;
    let name = line[..eq].trim().to_string();
    let rest = line[eq + 1..].trim();
    if !rest.starts_with('{') || !rest.ends_with('}') {
        return None;
    }
    let css = rest[1..rest.len() - 1].trim().to_string();
    if name.is_empty() {
        return None;
    }
    Some((name, css))
}

/// parse the css tag of a text like `{a,b}`
pub fn css_tags(content: &str) -> Option<Vec<String>> {
    let s = content.trim();
    if !s.starts_with('{') {
        return None;
    }
    let end = s.find('}')?;
    let inner = &s[1..end];
    let tags: Vec<String> = inner
        .split(',')
        .map(|t| t.trim().to_string())
        .filter(|t| !t.is_empty())
        .collect();
    if tags.is_empty() {
        return None;
    }
    if !tags.iter().all(|t| t.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-')) {
        return None;
    }
    Some(tags)
}

#[derive(Debug, Clone)]
pub struct FragmentTree {
    fragment: Fragment,
    css_tag: Vec<String>,
    enclosing: Vec<FragmentTree>,
}

impl FragmentTree {
    fn new(fragment: Fragment) -> Self {
        FragmentTree { fragment, css_tag: vec![], enclosing: vec![] }
    }
    fn can_fit(&self, other: &FragmentTree) -> bool {
        self.fragment.can_fit(&other.fragment)
    }
    fn enclose_deep_first(&mut self, other: &FragmentTree) -> bool {
        for child in self.enclosing.iter_mut() {
            if child.enclose_deep_first(other) {
                return true;
            }
        }
        if self.can_fit(other) {
            if let Fragment::CellText(t) = &other.fragment {
                if let Some(tags) = css_tags(&t.content) {
                    self.css_tag.extend(tags);
                    return true;
                }
            }
            self.enclosing.push(other.clone());
            true
        } else {
            false
        }
    }
    pub fn enclose_fragments(fragments: Vec<Fragment>) -> Vec<FragmentTree> {
        let trees: Vec<FragmentTree> = fragments.into_iter().map(FragmentTree::new).collect();
        Self::enclose_recursive(trees)
    }
    fn enclose_recursive(trees: Vec<FragmentTree>) -> Vec<FragmentTree> {
        let original_len = trees.len();
        let merged = Self::second_pass_enclose(trees);
        if merged.len() < original_len {
            Self::enclose_recursive(merged)
        } else {
            merged
        }
    }
    fn second_pass_enclose(trees: Vec<FragmentTree>) -> Vec<FragmentTree> {
        let mut new_trees: Vec<FragmentTree> = vec![];
        for tree in trees.into_iter() {
            let is_enclosed = new_trees.iter_mut().rev().any(|nt| nt.enclose_deep_first(&tree));
            if !is_enclosed {
                new_trees.push(tree);
            }
        }
        new_trees
    }
    fn render(&self, settings: &Settings, out: &mut String, indent: &str) {
        out.push_str(indent);
        out.push_str(&self.fragment.to_svg(settings.scale, &self.css_tag, true));
        out.push('\n');
        for child in &self.enclosing {
            child.render(settings, out, indent);
        }
    }
}

fn style(settings: &Settings, legend: &[(String, String)]) -> String {
    let mut s = String::new();
    s.push_str(&format!(
        "  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{
  stroke: {stroke};
  stroke-width: {sw};
  stroke-opacity: 1;
