fn run_build(args: &[String]) {
    let mut input: Option<String> = None;
    let mut outdir: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        let take_value = |i: &mut usize, name: &str| -> String {
            *i += 1;
            if *i >= args.len() || (args[*i].starts_with('-') && args[*i].len() > 1) {
                error_exit(
                    &format!("The argument '--{} <{}>' requires a value but none was supplied", name, name),
                    &format!("USAGE:\n    executable build --{} <{}>", name, name),
                );
            }
            args[*i].clone()
        };
        match arg.as_str() {
            "-h" | "--help" => {
                println!("{}", BUILD_HELP);
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-build 0.0.1");
                std::process::exit(0);
            }
            "-i" | "--input" => {
                input = Some(take_value(&mut i, "input"));
            }
            "-o" | "--outdir" => {
                outdir = Some(take_value(&mut i, "outdir"));
            }
            _ => {
                if let Some(v) = arg.strip_prefix("--input=") {
                    input = Some(v.to_string());
                } else if let Some(v) = arg.strip_prefix("--outdir=") {
                    outdir = Some(v.to_string());
                } else if let Some(v) = arg.strip_prefix("-i") {
                    if !v.is_empty() {
                        input = Some(v.to_string());
                    }
                } else if let Some(v) = arg.strip_prefix("-o") {
                    if !v.is_empty() {
                        outdir = Some(v.to_string());
                    }
                } else {
                    unexpected(arg, BUILD_USAGE);
                }
            }
        }
        i += 1;
    }
    let pattern = input.unwrap_or_else(|| "*.bob".to_string());
    let outdir = outdir.unwrap_or_else(|| ".".to_string());
    let files = crate::glob::glob(&pattern);
    for f in files {
        let content = match std::fs::read_to_string(&f) {
            Ok(c) => c,
            Err(_) => continue,
        };
        let svg = crate::to_svg(&content, &Settings::default());
        let path = std::path::Path::new(&f);
        let stem = path.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
        let out = std::path::Path::new(&outdir).join(format!("{}.svg", stem));
        let _ = std::fs::write(out, svg);
    }
}
