fn localize(cells: &BTreeMap<Cell, char>) -> (BTreeMap<Cell, char>, Cell) {
    let minx = cells.keys().map(|c| c.x).min().unwrap_or(0);
    let miny = cells.keys().map(|c| c.y).min().unwrap_or(0);
    let offset = Cell::new(minx, miny);
    let localized = cells.iter().map(|(c, ch)| (Cell::new(c.x - minx, c.y - miny), *ch)).collect();
