}

fn build_entries() -> Vec<ArtEntry> {
    let mut entries: Vec<ArtEntry> = vec![];
    let kinds_order = [
        vec![ArcKind::Circle],
        vec![
            ArcKind::ThreeQuartersNoTl,
            ArcKind::ThreeQuartersNoTr,
            ArcKind::ThreeQuartersNoBl,
            ArcKind::ThreeQuartersNoBr,
