}

fn make_fragment(kind: ArcKind, center: Point, r: f32) -> Fragment {
    let top = Point::new(center.x, center.y - r);
    let bottom = Point::new(center.x, center.y + r);
    let left = Point::new(center.x - r, center.y);
    let right = Point::new(center.x + r, center.y);
    let arc = |s: Point, e: Point, large: bool, sweep: bool| {
        Fragment::Arc(Arc { start: s, end: e, radius: r, large_arc: large, sweep_flag: sweep })
    };
    match kind {
        ArcKind::Circle => Fragment::Circle(Circle::new(center, r, false)),
        ArcKind::ThreeQuartersNoTl => arc(top, left, true, true),
        ArcKind::ThreeQuartersNoTr => arc(top, right, true, false),
        ArcKind::ThreeQuartersNoBl => arc(left, bottom, true, true),
        ArcKind::ThreeQuartersNoBr => arc(right, bottom, true, false),
        ArcKind::HalfTop => arc(left, right, false, true),
        ArcKind::HalfBottom => arc(left, right, false, false),
        ArcKind::HalfLeft => arc(top, bottom, false, false),
        ArcKind::HalfRight => arc(top, bottom, false, true),
        ArcKind::QuarterTl => arc(top, left, false, false),
        ArcKind::QuarterTr => arc(top, right, false, true),
        ArcKind::QuarterBl => arc(left, bottom, false, false),
        ArcKind::QuarterBr => arc(right, bottom, false, true),
    }
}

/// try to match the span against circle / arc arts.
/// returns the fragment and the remaining span
pub fn endorse(span: &Span) -> Option<(Fragment, Span)> {
    let cells: BTreeMap<Cell, char> = span.0.iter().cloned().collect();
    if cells.is_empty() {
        return None;
    }
    let (localized, offset) = localize(&cells);
    for entry in entries().iter() {
        if entry.cells.iter().all(|(c, ch)| localized.get(c) == Some(ch)) {
            let center = Point::new(
                entry.center.x + offset.x as f32 * CELL_WIDTH,
                entry.center.y + offset.y as f32 * CELL_HEIGHT,
            );
            let frag = make_fragment(entry.kind, center, entry.radius);
            let remaining: Vec<(Cell, char)> = span
                .0
                .iter()
                .filter(|(c, _)| !entry.cells.contains_key(&Cell::new(c.x - offset.x, c.y - offset.y)))
                .cloned()
                .collect();
            return Some((frag, Span(remaining)));
        }
    }
    None
}
