import sys
def group_adjacents(s, rev=True):
    cells = []
    for y, line in enumerate(s.split('\n')):
        for x, ch in enumerate(line):
            if ch != ' ': cells.append(((x,y), ch))
    cells.sort(key=lambda c: (c[0][1], c[0][0]))
    spans = []
    for (c, ch) in cells:
        order = reversed(range(len(spans))) if rev else range(len(spans))
        placed = False
        for i in order:
            if any(abs(c[0]-d[0])<=1 and abs(c[1]-d[1])<=1 for (d,_) in spans[i]):
                spans[i].append((c,ch)); placed = True; break
        if not placed: spans.append([(c,ch)])
    # second pass merge
    def can_merge(a,b):
        return any(abs(c[0]-d[0])<=1 and abs(c[1]-d[1])<=1 for (c,_) in a for (d,_) in b)
    while True:
        n = len(spans)
        new = []
        for sp in spans:
            merged = False
            for i in reversed(range(len(new))):
                if can_merge(new[i], sp):
                    new[i] = new[i] + sp; merged = True; break
            if not merged: new.append(sp)
        spans = new
        if len(spans) == n: break
    return spans
