/// snap a point to the cell containing it
fn snap(p: Point) -> Cell {
    Cell::new((p.x / CELL_WIDTH).floor() as i32, (p.y / CELL_HEIGHT).floor() as i32)
}

fn cell_bounds(frags: &[Fragment]) -> (Cell, Cell) {
    let mut minx = f32::MAX;
    let mut miny = f32::MAX;
    let mut maxx = f32::MIN;
    let mut maxy = f32::MIN;
    for f in frags {
        let (a, b) = f.bounds();
        minx = minx.min(a.x);
